def max_and_sum(nums: list[int]) -> tuple[int, int]:
    if not nums:
        raise ValueError('nums must not be empty')
    lo = hi = nums[0]
    for x in nums[1:]:
        if x < lo:
            lo = x
        elif x > hi:
            hi = x
    return lo, hi, hi - lo
